"use client";

import { Waveform as WaveformPrimitive } from "@audio-ui/react";
import { cn } from "@/lib/utils";

/** Matches `linearWaveformPath`'s own default width/height, so a `viewBox` "just works" when the path was generated with defaults. */
const DEFAULT_VIEW_BOX = "0 0 800 100";

interface WaveformProps extends WaveformPrimitive.RootProps {
  /** The waveform's SVG path `d` string — see `linearWaveformPath` in `lib/waveform-path.ts`. Rendered twice internally: the full shape, and a value-clipped "progress" copy. */
  d: string;
  viewBox?: string;
}

export function Waveform({
  className,
  d,
  viewBox = DEFAULT_VIEW_BOX,
  ...props
}: WaveformProps) {
  return (
    <WaveformPrimitive.Root className="w-full min-w-0" {...props}>
      <WaveformPrimitive.Track
        className={cn(
          "relative h-20 overflow-hidden rounded-2xl border border-transparent bg-card ring-1 ring-foreground/10 relative w-full min-w-0 touch-none select-none",
          "focus-within:outline-none",
          "data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50",
          className
        )}
        data-slot="waveform"
      >
        <WaveformPrimitive.Svg viewBox={viewBox}>
          <WaveformPrimitive.Path className="pointer-events-none fill-none stroke-border stroke-2" d={d} />
          <WaveformPrimitive.Progress className="pointer-events-none fill-none stroke-primary stroke-2" d={d} />
        </WaveformPrimitive.Svg>
        <WaveformPrimitive.Thumb className="size-3.5 rounded-full bg-card ring-1 ring-foreground/10 transition-[color,box-shadow] hover:ring-4 hover:ring-ring/50 focus-visible:ring-4 focus-visible:ring-ring/50 active:ring-4 active:ring-ring/50 motion-reduce:transition-none" />
      </WaveformPrimitive.Track>
    </WaveformPrimitive.Root>
  );
}
